// A standalone script showcasing how Dart 3 records can act as
// lightweight, immutable “data classes”.

// Readable type aliases for our record shapes.
typedef Person  = ({String name, int age});
typedef Address = ({String street, String city});
typedef Employee = ({Person person, Address address, int id});

@pragma('vm:entry-point')
void main() {
  // ------------------------------------------------------------------
  // 1. Creating record-based data objects.
  // ------------------------------------------------------------------
  const Person  alice     = (name: 'Alice', age: 30);
  const Address aliceHome = (street: '123 Main St', city: 'Metropolis');
  const Employee employeeAlice = (
    person:  alice,
    address: aliceHome,
    id:      1001,
  );

  // ------------------------------------------------------------------
  // 2. Accessing fields (dot notation).
  // ------------------------------------------------------------------
  print('Employee #${employeeAlice.id}: '
        '${employeeAlice.person.name} (${employeeAlice.person.age}) '
        'from ${employeeAlice.address.city}');

  // ------------------------------------------------------------------
  // 3. Records have structural equality.
  // ------------------------------------------------------------------
  const anotherAlice = (name: 'Alice', age: 30);
  print('Is anotherAlice equal to alice? ${anotherAlice == alice}\n');

  // ------------------------------------------------------------------
  // 4. Destructuring with pattern matching.
  // ------------------------------------------------------------------
  final (:person, :address, :id) = employeeAlice;      // top-level record
  final (:name, :age)            = person;             // nested record
  final (:street, :city)         = address;            // nested record

  print('Destructured -> '
        'id:$id name:$name age:$age street:$street city:$city');

  // ------------------------------------------------------------------
  // 5. “Copy-with” by building a new record.
  // ------------------------------------------------------------------
  final Employee birthdayAlice = (
    person:  (name: name, age: age + 1), // Alice had a birthday
    address: address,
    id:      id,
  );

  print('After birthday, ${birthdayAlice.person.name} is '
        '${birthdayAlice.person.age} years old.\n');

  // ------------------------------------------------------------------
  // 6. Aggregating record objects in collections.
  // ------------------------------------------------------------------
  final team = <Employee>[
    employeeAlice,
    (
      person:  (name: 'Bob',   age: 25),
      address: (street: '456 Side Rd', city: 'Gotham'),
      id:      1002,
    ),
    (
      person:  (name: 'Carol', age: 40),
      address: (street: '789 High St', city: 'Star City'),
      id:      1003,
    ),
  ];

  // Sort team members by age using a record field.
  team.sort((a, b) => a.person.age.compareTo(b.person.age));

  print('Team ordered by age:');
  for (final member in team) {
    print('• ${member.person.name} (${member.person.age})');
  }
}

